const resp = $input.first().json;
const table = resp?.results?.[0]?.tables?.[0];
if (!table) {
  return [{ json: { rows: [], row_count: 0, truncated: false, error: 'No results table in Power BI response', raw: resp } }];
}

const rawRows = table.rows || [];

// Strip '[Table].[Column]' brackets → just the Column part
const clean = (k) => {
  const m = k.match(/\[([^\]]+)\]$/);
  return m ? m[1] : k.replace(/^\[|\]$/g, '');
};

const rows = rawRows.map(row => {
  const out = {};
  for (const k of Object.keys(row)) out[clean(k)] = row[k];
  return out;
});

const MAX = 200;
if (rows.length > MAX) {
  return [{ json: {
    rows: rows.slice(0, MAX),
    row_count: MAX,
    total_rows: rows.length,
    truncated: true,
    note: `Showing ${MAX} of ${rows.length} rows. Add TOPN, a filter, or an aggregation to narrow results.`
  } }];
}
return [{ json: { rows, row_count: rows.length, truncated: false } }];
